"use client";

import React, { useState } from "react";
import { TESTIMONIALS } from "@/lib/data";

export function TestimonialsSection() {
  const [currentIndex, setCurrentIndex] = useState(0);
  const current = TESTIMONIALS[currentIndex];

  const handlePrev = () => {
    setCurrentIndex((prev) => (prev === 0 ? TESTIMONIALS.length - 1 : prev - 1));
  };

  const handleNext = () => {
    setCurrentIndex((prev) => (prev === TESTIMONIALS.length - 1 ? 0 : prev + 1));
  };

  return (
    <section className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-20 relative">
      <div className="absolute inset-0 -z-10 rounded-3xl bg-gradient-to-br from-blue-50/50 via-white to-orange-50/50 opacity-60 blur-3xl pointer-events-none" />

      {/* Header */}
      <div className="text-center mb-16">
        <div className="inline-block px-4 py-1.5 bg-gradient-to-r from-blue-600/10 to-fb8500/10 rounded-full border border-fb8500/30 mb-4">
          <span className="text-xs sm:text-sm font-bold bg-gradient-to-r from-blue-600 to-fb8500 bg-clip-text text-transparent">
            ⭐ Customer Testimonials
          </span>
        </div>
        <h2 className="text-3xl sm:text-5xl font-extrabold text-neutral-900 mb-4">
          What Our <span className="bg-gradient-to-r from-blue-600 to-fb8500 bg-clip-text text-transparent">Customers Say</span>
        </h2>
        <p className="text-base sm:text-lg text-neutral-600 max-w-2xl mx-auto leading-relaxed">
          Join thousands of satisfied customers who have found trusted professionals on WrkZone
        </p>
      </div>

      {/* Featured Testimonial Card */}
      <div className="max-w-4xl mx-auto">
        <div className="relative group">
          <div
            className={`absolute inset-0 bg-gradient-to-br ${current.color} opacity-10 rounded-3xl blur-2xl group-hover:opacity-15 transition-opacity`}
          />
          <div className="relative bg-white/90 backdrop-blur-md rounded-3xl p-8 sm:p-12 ring-1 ring-neutral-200/80 shadow-xl group-hover:ring-fb8500/40 transition-all duration-300">
            {/* Stars */}
            <div className="flex gap-1 mb-6 text-xl">
              {"⭐".repeat(current.rating)}
            </div>

            {/* Quote */}
            <p className="text-lg sm:text-2xl text-neutral-800 mb-10 leading-relaxed font-serif italic">
              &ldquo;{current.text}&rdquo;
            </p>

            {/* Author Details */}
            <div className="flex items-center gap-4 pb-8 border-b border-neutral-100">
              <div
                className={`w-14 h-14 rounded-full bg-gradient-to-br ${current.color} flex items-center justify-center text-3xl shadow-md text-white`}
              >
                {current.avatar}
              </div>
              <div>
                <h3 className="text-lg font-bold text-neutral-900">{current.name}</h3>
                <p className="text-sm text-neutral-600">
                  📍 {current.city} • <span className="font-semibold text-fb8500">{current.service}</span>
                </p>
              </div>
            </div>

            {/* Navigation Controls */}
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4 mt-6">
              <div className="flex items-center gap-2">
                <button
                  onClick={handlePrev}
                  className="p-3 rounded-full bg-neutral-100 hover:bg-neutral-200 text-neutral-800 transition-all font-bold text-lg"
                  aria-label="Previous testimonial"
                >
                  ←
                </button>
                <button
                  onClick={handleNext}
                  className="p-3 rounded-full bg-neutral-100 hover:bg-neutral-200 text-neutral-800 transition-all font-bold text-lg"
                  aria-label="Next testimonial"
                >
                  →
                </button>
              </div>

              {/* Author Tab Buttons */}
              <div className="flex flex-wrap items-center gap-2">
                {TESTIMONIALS.map((t, idx) => (
                  <button
                    key={t.name}
                    onClick={() => setCurrentIndex(idx)}
                    className={`px-3 py-1.5 rounded-full text-xs font-semibold transition-all ${
                      currentIndex === idx
                        ? "bg-fb8500 text-white shadow-md shadow-fb8500/25 scale-105"
                        : "bg-neutral-100 text-neutral-700 hover:bg-neutral-200"
                    }`}
                  >
                    <span>{t.avatar}</span> {t.name.split(" ")[0]}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
